import{_ as t,o as n,c as a,a2 as o}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"Trades and journal","description":"Connected execution imports, current manual/simulated trade behavior, journal entries, decision reviews, and the difference between execution records and notes.","frontmatter":{"title":"Trades and journal","description":"Connected execution imports, current manual/simulated trade behavior, journal entries, decision reviews, and the difference between execution records and notes.","audience":"user","status":"current","last_verified":"2026-07-19T00:00:00.000Z"},"headers":[],"relativePath":"use-zenin/trades-and-journal.md","filePath":"use-zenin/trades-and-journal.md","lastUpdated":null}'),r={name:"use-zenin/trades-and-journal.md"};function i(d,e,s,l,u,c){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="trades-and-journal" tabindex="-1">Trades and journal</h1><p>Zenin separates <strong>execution records</strong> (what happened) from <strong>journal entries</strong> (what you thought and decided). Keeping them distinct is the point of the journal.</p><h2 id="connected-execution-imports" tabindex="-1">Connected execution imports</h2><p>When a connected account syncs, completed trades become <strong>execution records</strong>:</p><ul><li>symbol, side, quantity, price, notional, fees, and timestamp;</li><li>the source the execution came from;</li><li>a link back to the holding it affected.</li></ul><p>These are factual records, not opinions.</p><h2 id="current-manual-simulated-trade-behavior" tabindex="-1">Current manual / simulated trade behavior</h2><p>Where a connection is not available, or you want to plan a trade, you can record a trade manually or as a simulation. Treat manual entries as <strong>your input</strong>, not imported brokerage data:</p><ul><li>A manual trade is attributed to you, not a source.</li><li>A simulated trade is a plan, not an executed position.</li></ul><p>This keeps &quot;what I intended&quot; separate from &quot;what actually executed.&quot;</p><h2 id="journal-entries" tabindex="-1">Journal entries</h2><p>A <strong>journal entry</strong> captures the decision and its rationale:</p><ul><li>the thesis and evidence;</li><li>the planned entry/exit or rule;</li><li>notes and attached research.</li></ul><p>Journal entries can be linked to executions so the decision and the outcome sit together.</p><h2 id="decision-reviews" tabindex="-1">Decision reviews</h2><p>After the trade plays out, add a <strong>decision review</strong>:</p><ul><li>what happened versus the plan;</li><li>the lesson or rule to repeat / remove;</li><li>handoff to the next session.</li></ul><p>Reviews turn the journal from a log into a feedback loop.</p><h2 id="execution-record-vs-note" tabindex="-1">Execution record vs note</h2><table tabindex="0"><thead><tr><th></th><th>Execution record</th><th>Journal note</th></tr></thead><tbody><tr><td>Source</td><td>Imported from a connection or entered by you</td><td>Written by you</td></tr><tr><td>Represents</td><td>What happened</td><td>What you thought / decided</td></tr><tr><td>Editable facts</td><td>No (it is a record)</td><td>Yes</td></tr><tr><td>Used for</td><td>Attribution, P&amp;L, audit</td><td>Reflection, review</td></tr></tbody></table><hr><h2 id="what-this-does-does-not-do" tabindex="-1">What this does / does not do</h2><p><strong>What this does</strong></p><ul><li>Imports executions from connected accounts as factual records.</li><li>Lets you record manual or simulated trades separately.</li><li>Links journal entries and reviews to executions.</li></ul><p><strong>What it does not do</strong></p><ul><li>It does not execute trades.</li><li>It does not treat a simulated trade as a real position.</li><li>It does not alter an execution record&#39;s facts.</li></ul><p><strong>Data source and freshness</strong></p><p>Executions come from your connected read-only sources (SnapTrade brokerage, exchange API keys). Manual and simulated trades are entered by you and marked accordingly. Journal content is created in-app and persisted in your workspace.</p>',28)])])}const m=t(r,[["render",i]]);export{p as __pageData,m as default};
